  def battery_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var battery_assessment: Power_Propulsion_Availability_Supervisor.BatteryAssessment.Type = $

  def put_battery_assessment(value : Power_Propulsion_Availability_Supervisor.BatteryAssessment.Type) : Unit = {
    Contract(
      Modifies(battery_assessment),
      Ensures(
        battery_assessment == value
      )
    )
    Spec {
      battery_assessment = value
    }

    Art.putValue(battery_assessment_Id, Power_Propulsion_Availability_Supervisor.BatteryAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

